63	static int pin_code_reply(struct bt_conn *conn, const char *pin, uint8_t len)
64	{
65		struct bt_hci_cp_pin_code_reply *cp;
66		struct net_buf *buf;
67	
68		LOG_DBG("");
69	
70		if (len > sizeof(cp->pin_code)) {
71			return -EINVAL;
72		}
73	
74		buf = bt_hci_cmd_create(BT_HCI_OP_PIN_CODE_REPLY, sizeof(*cp));
75		if (!buf) {
76			return -ENOBUFS;
77		}
78	
79		cp = net_buf_add(buf, sizeof(*cp));
80	
81		bt_addr_copy(&cp->bdaddr, &conn->br.dst);
82		cp->pin_len = len;
83		memset(cp->pin_code, 0, sizeof(cp->pin_code));
84		memcpy(cp->pin_code, pin, len);
85	
86		return bt_hci_cmd_send_sync(conn->hdev, BT_HCI_OP_PIN_CODE_REPLY, buf, NULL);
87	}
