124	static void pin_code_req(struct bt_conn *conn)
125	{
126		if (conn->hdev->bt_auth && conn->hdev->bt_auth->pincode_entry) {
127			bool secure = false;
128	
129			if (conn->required_sec_level == BT_SECURITY_L3) {
130				secure = true;
131			}
132	
133			atomic_set_bit(conn->flags, BT_CONN_USER);
134			atomic_set_bit(conn->flags, BT_CONN_BR_PAIRING);
135			conn->hdev->bt_auth->pincode_entry(conn, secure);
136		} else {
137			pin_code_neg_reply(conn->hdev, &conn->br.dst);
138		}
139	}
