382	int bt_ssp_auth_passkey_entry(struct bt_conn *conn, unsigned int passkey)
383	{
384		/* User entered passkey, reset user state. */
385		if (!atomic_test_and_clear_bit(conn->flags, BT_CONN_USER)) {
386			return -EPERM;
387		}
388	
389		if (conn->br.pairing_method == PASSKEY_INPUT) {
390			return ssp_passkey_reply(conn, passkey);
391		}
392	
393		return -EINVAL;
394	}
