411	int bt_ssp_auth_cancel(struct bt_conn *conn)
412	{
413		/* Allow user cancel authentication, then reset user state. */
414		if (!atomic_test_and_clear_bit(conn->flags, BT_CONN_USER)) {
415			return -EPERM;
416		}
417	
418		switch (conn->br.pairing_method) {
419		case JUST_WORKS:
420		case PASSKEY_CONFIRM:
421			return ssp_confirm_neg_reply(conn);
422		case PASSKEY_INPUT:
423			return ssp_passkey_neg_reply(conn);
424		case PASSKEY_DISPLAY:
425			return bt_conn_disconnect(conn,
426						  BT_HCI_ERR_AUTH_FAIL);
427		case LEGACY:
428			return pin_code_neg_reply(conn->hdev, &conn->br.dst);
429		default:
430			break;
431		}
432	
433		return -EINVAL;
434	}
