453	void bt_hci_link_key_notify(struct bt_dev *hdev, struct net_buf *buf)
454	{
455		struct bt_hci_evt_link_key_notify *evt = (void *)buf->data;
456		struct bt_conn *conn;
457	
458		conn = bt_conn_lookup_addr_br_mc(hdev->dev_id, &evt->bdaddr);
459		if (!conn) {
460			LOG_ERR("Can't find conn for %s", bt_addr_str(&evt->bdaddr));
461			return;
462		}
463	
464		LOG_DBG("%s, link type 0x%02x", bt_addr_str(&evt->bdaddr), evt->key_type);
465	
466		if (IS_ENABLED(CONFIG_BT_SMP_SC_ONLY) && (evt->key_type != BT_LK_AUTH_COMBINATION_P256)) {
467			/*
468			 * When in Secure Connections Only mode, all services
469			 * (except those allowed to have Security Mode 4, Level 0)
470			 * available on the BR/EDR physical transport require Security
471			 * Mode 4, Level 4.
472			 * Link key type should be P-256 based Secure Simple Pairing
473			 * and Secure Authentication.
474			 */
475			LOG_WRN("For SC only mode, link key type should be %d",
476				BT_LK_AUTH_COMBINATION_P256);
477			ssp_pairing_complete(conn, bt_security_err_get(BT_HCI_ERR_AUTH_FAIL));
478			bt_conn_disconnect(conn, BT_HCI_ERR_AUTH_FAIL);
479			bt_conn_unref(conn);
480			return;
481		}
482	
483		if (!conn->br.link_key) {
484			conn->br.link_key = bt_keys_get_link_key(hdev, &evt->bdaddr);
485		}
486		if (!conn->br.link_key) {
487			LOG_ERR("Can't update keys for %s", bt_addr_str(&evt->bdaddr));
488			bt_conn_unref(conn);
489			return;
490		}
491	
492		/* clear any old Link Key flags */
493		conn->br.link_key->flags = 0U;
494		conn->br.link_key->key_type = evt->key_type;
495	
496		switch (evt->key_type) {
497		case BT_LK_COMBINATION:
498			/*
499			 * Setting Combination Link Key as AUTHENTICATED means it was
500			 * successfully generated by 16 digits wide PIN code.
501			 */
502			if (atomic_test_and_clear_bit(conn->flags,
503						      BT_CONN_BR_LEGACY_SECURE)) {
504				conn->br.link_key->flags |= BT_LINK_KEY_AUTHENTICATED;
505			}
506			memcpy(conn->br.link_key->val, evt->link_key, 16);
507			break;
508		case BT_LK_AUTH_COMBINATION_P192:
509			conn->br.link_key->flags |= BT_LINK_KEY_AUTHENTICATED;
510			__fallthrough;
511		case BT_LK_UNAUTH_COMBINATION_P192:
512			memcpy(conn->br.link_key->val, evt->link_key, 16);
513			break;
514		case BT_LK_AUTH_COMBINATION_P256:
515			conn->br.link_key->flags |= BT_LINK_KEY_AUTHENTICATED;
516			__fallthrough;
517		case BT_LK_UNAUTH_COMBINATION_P256:
518			conn->br.link_key->flags |= BT_LINK_KEY_SC;
519	
520			memcpy(conn->br.link_key->val, evt->link_key, 16);
521			break;
522		default:
523			LOG_WRN("Unsupported Link Key type %u", evt->key_type);
524			(void)memset(conn->br.link_key->val, 0,
525				     sizeof(conn->br.link_key->val));
526			break;
527		}
528	
529		if (IS_ENABLED(CONFIG_BT_SETTINGS) &&
530		    !atomic_test_bit(conn->flags, BT_CONN_BR_NOBOND)) {
531			bt_keys_link_key_store(hdev, conn->br.link_key);
532		}
533	
534		bt_conn_unref(conn);
535	}
