738	void bt_hci_ssp_complete(struct bt_dev *hdev, struct net_buf *buf)
739	{
740		struct bt_hci_evt_ssp_complete *evt = (void *)buf->data;
741		struct bt_conn *conn;
742	
743		LOG_DBG("status 0x%02x", evt->status);
744	
745		conn = bt_conn_lookup_addr_br_mc(hdev->dev_id, &evt->bdaddr);
746		if (!conn) {
747			LOG_ERR("Can't find conn for %s", bt_addr_str(&evt->bdaddr));
748			return;
749		}
750	
751		/* Mark no-bond so that link-key will be removed on disconnection */
752		if (ssp_get_auth(conn) < BT_HCI_DEDICATED_BONDING) {
753			atomic_set_bit(conn->flags, BT_CONN_BR_NOBOND);
754		}
755	
756		ssp_pairing_complete(conn, bt_security_err_get(evt->status));
757		if (evt->status) {
758			bt_conn_disconnect(conn, BT_HCI_ERR_AUTH_FAIL);
759		}
760	
761		bt_conn_unref(conn);
762	}
