89	int bt_conn_auth_pincode_entry(struct bt_conn *conn, const char *pin)
90	{
91		size_t len;
92	
93		if (!conn->hdev->bt_auth) {
94			return -EINVAL;
95		}
96	
97		if (!bt_conn_is_type(conn, BT_CONN_TYPE_BR)) {
98			LOG_DBG("Invalid connection type: %u for %p", conn->type, conn);
99			return -EINVAL;
100		}
101	
102		len = strlen(pin);
103		if (len > 16) {
104			return -EINVAL;
105		}
106	
107		if (conn->required_sec_level == BT_SECURITY_L3 && len < 16) {
108			LOG_WRN("PIN code for %s is not 16 bytes wide", bt_addr_str(&conn->br.dst));
109			return -EPERM;
110		}
111	
112		/* Allow user send entered PIN to remote, then reset user state. */
113		if (!atomic_test_and_clear_bit(conn->flags, BT_CONN_USER)) {
114			return -EPERM;
115		}
116	
117		if (len == 16) {
118			atomic_set_bit(conn->flags, BT_CONN_BR_LEGACY_SECURE);
119		}
120	
121		return pin_code_reply(conn, pin, len);
122	}
