141	static uint8_t get_io_capa(struct bt_dev *hdev)
142	{
143		if (!hdev->bt_auth) {
144			return BT_IO_NO_INPUT_OUTPUT;
145		}
146	
147		if (hdev->bt_auth->passkey_confirm && hdev->bt_auth->passkey_display) {
148			return BT_IO_DISPLAY_YESNO;
149		}
150	
151		if (hdev->bt_auth->passkey_entry) {
152			return BT_IO_KEYBOARD_ONLY;
153		}
154	
155		if (hdev->bt_auth->passkey_display) {
156			return BT_IO_DISPLAY_ONLY;
157		}
158	
159		return BT_IO_NO_INPUT_OUTPUT;
160	}
