167	static uint8_t ssp_get_auth(const struct bt_conn *conn)
168	{
169		/* Validate no bond auth request, and if valid use it. */
170		if ((conn->br.remote_auth == BT_HCI_NO_BONDING) ||
171		    ((conn->br.remote_auth == BT_HCI_NO_BONDING_MITM) &&
172		     (ssp_pair_method(conn) > JUST_WORKS))) {
173			return conn->br.remote_auth;
174		}
175	
176		/* Local & remote have enough IO capabilities to get MITM protection. */
177		if (ssp_pair_method(conn) > JUST_WORKS) {
178			return conn->br.remote_auth | BT_MITM;
179		}
180	
181		/* No MITM protection possible so ignore remote MITM requirement. */
182		return (conn->br.remote_auth & ~BT_MITM);
183	}
