222	static void ssp_pairing_complete(struct bt_conn *conn, uint8_t status)
223	{
224		/* When the ssp pairing complete event notified,
225		 * clear the pairing flag.
226		 */
227		atomic_clear_bit(conn->flags, BT_CONN_BR_PAIRING);
228		atomic_set_bit_to(conn->flags, BT_CONN_BR_PAIRED, !status);
229	
230		LOG_DBG("Pairing completed status %d", status);
231	
232		if (!status) {
233			bool bond = !atomic_test_bit(conn->flags, BT_CONN_BR_NOBOND);
234			struct bt_conn_auth_info_cb *listener, *next;
235	
236			SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&conn->hdev->bt_auth_info_cbs, listener,
237							  next, node) {
238				if (listener->pairing_complete) {
239					listener->pairing_complete(conn, bond);
240				}
241			}
242		} else {
243			struct bt_conn_auth_info_cb *listener, *next;
244	
245			SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&conn->hdev->bt_auth_info_cbs, listener,
246							  next, node) {
247				if (listener->pairing_failed) {
248					listener->pairing_failed(conn, status);
249				}
250			}
251		}
252	}
