254	static void ssp_auth(struct bt_conn *conn, uint32_t passkey)
255	{
256		conn->br.pairing_method = ssp_pair_method(conn);
257	
258		/*
259		 * If local required security is HIGH then MITM is mandatory.
260		 * MITM protection is no achievable when SSP 'justworks' is applied.
261		 */
262		if (conn->required_sec_level > BT_SECURITY_L2 &&
263		    conn->br.pairing_method == JUST_WORKS) {
264			LOG_DBG("MITM protection infeasible for required security");
265			ssp_confirm_neg_reply(conn);
266			return;
267		}
268	
269		switch (conn->br.pairing_method) {
270		case PASSKEY_CONFIRM:
271			atomic_set_bit(conn->flags, BT_CONN_USER);
272			conn->hdev->bt_auth->passkey_confirm(conn, passkey);
273			break;
274		case PASSKEY_DISPLAY:
275			atomic_set_bit(conn->flags, BT_CONN_USER);
276			conn->hdev->bt_auth->passkey_display(conn, passkey);
277			break;
278		case PASSKEY_INPUT:
279			atomic_set_bit(conn->flags, BT_CONN_USER);
280			conn->hdev->bt_auth->passkey_entry(conn);
281			break;
282		case JUST_WORKS:
283			/*
284			 * When local host works as pairing acceptor and 'justworks'
285			 * model is applied then notify user about such pairing request.
286			 * [BT Core 4.2 table 5.7, Vol 3, Part C, 5.2.2.6]
287			 */
288	#ifdef CONFIG_HCI_AUTO_REPLY_IN_JUST_WORK
289			if (conn->hdev->bt_auth && conn->hdev->bt_auth->pairing_confirm &&
290			    !atomic_test_bit(conn->flags,
291					     BT_CONN_BR_PAIRING_INITIATOR)) {
292				atomic_set_bit(conn->flags, BT_CONN_USER);
293				conn->hdev->bt_auth->pairing_confirm(conn);
294				break;
295			}
296	#else
297			if (conn->hdev->bt_auth && conn->hdev->bt_auth->passkey_confirm) {
298				atomic_set_bit(conn->flags, BT_CONN_USER);
299				conn->hdev->bt_auth->passkey_confirm(conn, 0xFFFFFFFF);
300				break;
301			}
302	#endif
303			ssp_confirm_reply(conn);
304			break;
305		default:
306			break;
307		}
308	}
