574	void bt_hci_link_key_req(struct bt_dev *hdev, struct net_buf *buf)
575	{
576		struct bt_hci_evt_link_key_req *evt = (void *)buf->data;
577		struct bt_conn *conn;
578	
579		LOG_DBG("%s", bt_addr_str(&evt->bdaddr));
580	
581		conn = bt_conn_lookup_addr_br_mc(hdev->dev_id, &evt->bdaddr);
582		if (!conn) {
583			LOG_ERR("Can't find conn for %s", bt_addr_str(&evt->bdaddr));
584			link_key_neg_reply(hdev, &evt->bdaddr);
585			return;
586		}
587	
588		if (!conn->br.link_key) {
589			conn->br.link_key = bt_keys_find_link_key(hdev, &evt->bdaddr);
590		}
591	
592		if (!conn->br.link_key) {
593			link_key_neg_reply(hdev, &evt->bdaddr);
594			bt_conn_unref(conn);
595			return;
596		}
597	
598		/*
599		 * Enforce regenerate by controller stronger link key since found one
600		 * in database not covers requested security level.
601		 */
602		if (!(conn->br.link_key->flags & BT_LINK_KEY_AUTHENTICATED) &&
603		    conn->required_sec_level > BT_SECURITY_L2) {
604			link_key_neg_reply(hdev, &evt->bdaddr);
605			bt_conn_unref(conn);
606			return;
607		}
608	
609		link_key_reply(hdev, &evt->bdaddr, conn->br.link_key->val);
610		bt_conn_unref(conn);
611	}
