671	void bt_hci_io_capa_req(struct bt_dev *hdev, struct net_buf *buf)
672	{
673		struct bt_hci_evt_io_capa_req *evt = (void *)buf->data;
674		struct net_buf *resp_buf;
675		struct bt_conn *conn;
676		struct bt_hci_cp_io_capability_reply *cp;
677		uint8_t auth;
678	
679		LOG_DBG("");
680	
681		conn = bt_conn_lookup_addr_br_mc(hdev->dev_id, &evt->bdaddr);
682		if (!conn) {
683			LOG_ERR("Can't find conn for %s", bt_addr_str(&evt->bdaddr));
684			return;
685		}
686	
687		resp_buf = bt_hci_cmd_create(BT_HCI_OP_IO_CAPABILITY_REPLY,
688					     sizeof(*cp));
689		if (!resp_buf) {
690			LOG_ERR("Out of command buffers");
691			bt_conn_unref(conn);
692			return;
693		}
694	
695		/*
696		 * Set authentication requirements when acting as pairing initiator to
697		 * 'dedicated bond' with MITM protection set if local IO capa
698		 * potentially allows it, and for acceptor, based on local IO capa and
699		 * remote's authentication set.
700		 */
701		if (atomic_test_bit(conn->flags, BT_CONN_BR_PAIRING_INITIATOR)) {
702			if (get_io_capa(conn->hdev) != BT_IO_NO_INPUT_OUTPUT) {
703				if (atomic_test_bit(conn->flags, BT_CONN_BR_GENERAL_BONDING)) {
704					auth = BT_HCI_GENERAL_BONDING_MITM;
705				} else {
706					auth = BT_HCI_DEDICATED_BONDING_MITM;
707				}
708			} else {
709				if (atomic_test_bit(conn->flags, BT_CONN_BR_GENERAL_BONDING)) {
710					auth = BT_HCI_GENERAL_BONDING;
711				} else {
712					auth = BT_HCI_DEDICATED_BONDING;
713				}
714			}
715	
716			if (conn->required_sec_level < BT_SECURITY_L3) {
717				/* If security level less than L3, clear MITM flag. */
718				auth = BT_HCI_SET_NO_MITM(auth);
719			}
720		} else {
721			auth = ssp_get_auth(conn);
722		}
723	
724		if (!atomic_test_bit(conn->flags, BT_CONN_BR_BONDABLE)) {
725			/* If bondable is false, clear bonding flag. */
726			auth = BT_HCI_SET_NO_BONDING(auth);
727		}
728	
729		cp = net_buf_add(resp_buf, sizeof(*cp));
730		bt_addr_copy(&cp->bdaddr, &evt->bdaddr);
731		cp->capability = get_io_capa(conn->hdev);
732		cp->authentication = auth;
733		cp->oob_data = 0U;
734		bt_hci_cmd_send_sync(hdev, BT_HCI_OP_IO_CAPABILITY_REPLY, resp_buf, NULL);
735		bt_conn_unref(conn);
736	}
