831	void bt_hci_auth_complete(struct bt_dev *hdev, struct net_buf *buf)
832	{
833		struct bt_hci_evt_auth_complete *evt = (void *)buf->data;
834		struct bt_conn *conn;
835		uint16_t handle = sys_le16_to_cpu(evt->handle);
836	
837		LOG_DBG("status 0x%02x, handle %u", evt->status, handle);
838	
839		conn = bt_conn_lookup_handle(hdev, handle, BT_CONN_TYPE_BR);
840		if (!conn) {
841			LOG_ERR("Can't find conn for handle %u", handle);
842			return;
843		}
844	
845		if (evt->status) {
846			/*
847			 * Inform layers above HCI about non-zero authentication
848			 * status to make them able cleanup pending jobs.
849			 */
850			bt_conn_security_changed(conn, evt->status,
851						 bt_security_err_get(evt->status));
852		} else {
853			link_encr(hdev, handle);
854		}
855	
856		bt_conn_unref(conn);
857	}
